struct BootstrapTimings {
    enabled: bool,
    started: Instant,
    checkpoint: Instant,
}

impl BootstrapTimings {
    fn from_environment() -> Self {
        let now = Instant::now();
        Self {
            enabled: std::env::var_os("G1_BOOTSTRAP_TIMINGS").is_some(),
            started: now,
            checkpoint: now,
        }
    }

    fn mark(&mut self, phase: &str) {
        if self.enabled {
            let now = Instant::now();
            eprintln!(
                "g1-bootstrap {phase}: phase={:.3}s total={:.3}s",
                now.duration_since(self.checkpoint).as_secs_f64(),
                now.duration_since(self.started).as_secs_f64()
            );
            self.checkpoint = now;
        }
    }
}

#[derive(Clone, Debug)]
struct PrivacyDomains {
    ranges: Vec<(SegmentId, std::ops::Range<usize>)>,
    modules: Option<(SourceBundle, crate::modules::ModuleResolution)>,
}

impl PrivacyDomains {
    fn bundle(bundle: &SourceBundle) -> Self {
        Self {
            ranges: bundle
                .segments()
                .iter()
                .map(|segment| {
                    (
                        segment
                            .id()
                            .expect("assembled bundle segments always have identities"),
                        segment.global_range(),
                    )
                })
                .collect(),
            modules: None,
        }
    }

    fn with_modules(
        mut self,
        bundle: &SourceBundle,
        modules: crate::modules::ModuleResolution,
    ) -> Self {
        self.modules = Some((bundle.clone(), modules));
        self
    }

    fn same_domain(&self, declaration: Span, use_site: Span) -> bool {
        if let Some((bundle, modules)) = &self.modules {
            return modules
                .owner(bundle, declaration)
                .is_some_and(|declaration| modules.owner(bundle, use_site) == Some(declaration));
        }
        self.domain(declaration)
            .is_some_and(|declaration| self.domain(use_site) == Some(declaration))
    }

    fn domain(&self, span: Span) -> Option<SegmentId> {
        self.ranges
            .iter()
            .find_map(|(id, range)| range.contains(&span.start).then_some(*id))
    }
}

#[derive(Clone, Debug)]
struct NominalPrivacy {
    declaration: Span,
    private_fields: BTreeSet<String>,
}

#[derive(Clone, Debug)]
struct LateNominalInfo {
    declaration: String,
    arguments: Vec<TypeId>,
    kind: NominalKind,
    privacy: NominalPrivacy,
    principal: UseInterval,
}

impl LateNominalInfo {
    fn struct_fields(&self) -> Option<&[(String, TypeId)]> {
        match &self.kind {
            NominalKind::Struct(fields) => Some(fields),
            NominalKind::Enum(_) => None,
        }
    }

    fn enum_variants(&self) -> Option<&[(String, Vec<TypeId>)]> {
        match &self.kind {
            NominalKind::Struct(_) => None,
            NominalKind::Enum(variants) => Some(variants),
        }
    }

    fn field_types(&self) -> Vec<TypeId> {
        match &self.kind {
            NominalKind::Struct(fields) => fields.iter().map(|(_, ty)| *ty).collect(),
            NominalKind::Enum(variants) => variants
                .iter()
                .flat_map(|(_, fields)| fields.iter().copied())
                .collect(),
        }
    }
}

#[derive(Clone, Debug, Default)]
struct RuntimeBindings {
    array_name: Option<String>,
    leaves: BTreeMap<String, Primitive>,
    host_leaves: BTreeMap<String, HostImportRole>,
    abort_leaf: Option<String>,
    trusted_domain: Option<SegmentId>,
}

impl RuntimeBindings {
    fn array_name(&self) -> Option<&str> {
        self.array_name.as_deref()
    }

    fn leaf(&self, name: &str) -> Option<Primitive> {
        self.leaves.get(name).copied()
    }

    fn host_leaf(&self, name: &str) -> Option<HostImportRole> {
        self.host_leaves.get(name).copied()
    }

    fn is_abort_leaf(&self, name: &str) -> bool {
        self.abort_leaf.as_deref() == Some(name)
    }

    fn call_is_authorized(&self, name: &str, span: Span, domains: &PrivacyDomains) -> bool {
        (self.leaf(name).is_none() && !self.is_abort_leaf(name))
            || self
                .trusted_domain
                .is_some_and(|authority| domains.domain(span) == Some(authority))
    }

    fn is_trusted_standard_library_body(&self, span: Span, domains: &PrivacyDomains) -> bool {
        self.trusted_domain
            .is_some_and(|authority| domains.domain(span) == Some(authority))
    }
}

#[derive(Clone)]
struct Signature {
    id: u32,
    params: Vec<TypeId>,
    result: TypeId,
    outward_protocols: Vec<u32>,
    region_contract: RegionContract,
}

#[derive(Clone, Default)]
struct RegionContract {
    param_regions: Vec<Option<core::RegionId>>,
    result_region: Option<core::RegionId>,
    result_variance: Option<typeck::Variance>,
    universal_facts: Vec<core::RegionFact>,
}

#[derive(Clone, Copy)]
struct CoreParameterContract<'a> {
    types: &'a [TypeId],
    regions: &'a RegionContract,
    receiver_captures: &'a [(String, TypeId, Span)],
}

impl RegionContract {
    fn permits_region(&self, actual: core::RegionId) -> bool {
        let Some(required) = self.result_region else {
            return true;
        };
        if actual == 0 {
            return false;
        }
        match self.result_variance.unwrap_or(typeck::Variance::Invariant) {
            typeck::Variance::Bivariant => true,
            typeck::Variance::Invariant => actual == required,
            typeck::Variance::Covariant => {
                actual == required
                    || self
                        .universal_facts
                        .iter()
                        .find(|fact| fact.region == required)
                        .is_some_and(|fact| fact.outlives.contains(&actual))
            }
            typeck::Variance::Contravariant => {
                actual == required
                    || self
                        .universal_facts
                        .iter()
                        .find(|fact| fact.region == actual)
                        .is_some_and(|fact| fact.outlives.contains(&required))
            }
        }
    }

    fn permits_return(&self, origin: &core::ReferenceOrigin) -> bool {
        self.permits_region(origin.region)
    }
}

fn source_region_contract(program: &Program, function: &crate::ast::Function) -> RegionContract {
    fn explicit_region(
        program: &Program,
        ty: &TypeSyntax,
        nominal_variance: &BTreeMap<String, Vec<typeck::Variance>>,
    ) -> Option<(String, typeck::Variance)> {
        let mut occurrences =
            typeck::type_lifetime_variance(program, ty, nominal_variance).into_iter();
        let occurrence = occurrences.next()?;
        occurrences.next().is_none().then_some(occurrence)
    }
    let nominal_variance = typeck::infer_nominal_variance(program);
    let mut names = BTreeSet::new();
    for parameter in &function.params {
        if let Some((name, _)) = explicit_region(program, &parameter.ty, &nominal_variance) {
            names.insert(name);
        }
    }
    if let Some(result) = &function.return_type
        && let Some((name, _)) = explicit_region(program, result, &nominal_variance)
    {
        names.insert(name);
    }
    if let Some(where_clause) = &function.where_clause {
        for constraint in &where_clause.lifetime_outlives {
            if !constraint.higher_ranked_lifetimes.is_empty() {
                continue;
            }
            names.insert(constraint.longer.name.clone());
            names.insert(constraint.shorter.name.clone());
        }
    }
    let ids = names
        .into_iter()
        .enumerate()
        .map(|(index, name)| (name, index as core::RegionId + 1))
        .collect::<BTreeMap<_, _>>();
    let mut next = ids.len() as core::RegionId + 1;
    let mut param_regions = Vec::with_capacity(function.params.len());
    for parameter in &function.params {
        if let Some((name, _)) = explicit_region(program, &parameter.ty, &nominal_variance) {
            param_regions.push(ids.get(&name).copied());
        } else if matches!(
            parameter.ty.kind,
            TypeSyntaxKind::SharedReference { referent: _, .. }
                | TypeSyntaxKind::UniqueReference { referent: _, .. }
        ) {
            param_regions.push(Some(next));
            next += 1;
        } else {
            param_regions.push(None);
        }
    }
    let result_occurrence = function
        .return_type
        .as_ref()
        .and_then(|ty| explicit_region(program, ty, &nominal_variance));
    let result_region = result_occurrence
        .as_ref()
        .and_then(|(name, _)| ids.get(name).copied());
    let result_variance = result_occurrence.map(|(_, variance)| variance);

    let all_regions = (1..next).collect::<Vec<_>>();
    let mut longer_by_shorter = all_regions
        .iter()
        .map(|region| (*region, BTreeSet::new()))
        .collect::<BTreeMap<_, _>>();
    if let Some(static_region) = ids.get("'static").copied() {
        for region in &all_regions {
            if *region != static_region {
                longer_by_shorter
                    .get_mut(region)
                    .unwrap()
                    .insert(static_region);
            }
        }
    }
    if let Some(where_clause) = &function.where_clause {
        for constraint in &where_clause.lifetime_outlives {
            if !constraint.higher_ranked_lifetimes.is_empty() {
                continue;
            }
            let longer = ids[&constraint.longer.name];
            let shorter = ids[&constraint.shorter.name];
            if longer != shorter {
                longer_by_shorter.get_mut(&shorter).unwrap().insert(longer);
            }
        }
    }
    loop {
        let previous = longer_by_shorter.clone();
        let mut changed = false;
        for longer in longer_by_shorter.values_mut() {
            let inherited = longer
                .iter()
                .flat_map(|region| previous.get(region).into_iter().flatten().copied())
                .collect::<Vec<_>>();
            for region in inherited {
                changed |= longer.insert(region);
            }
        }
        if !changed {
            break;
        }
    }
    let universal_facts = all_regions
        .into_iter()
        .map(|region| core::RegionFact {
            region,
            issued_at: 0,
            live_points: vec![0],
            ended_at: None,
            outlives: longer_by_shorter
                .remove(&region)
                .unwrap()
                .into_iter()
                .collect(),
        })
        .collect();
    RegionContract {
        param_regions,
        result_region,
        result_variance,
        universal_facts,
    }
}

fn validate_source_region_contract(
    function: &crate::ast::Function,
    contract: &RegionContract,
) -> Option<Diagnostic> {
    contract.result_region?;
    let supplied = contract
        .param_regions
        .iter()
        .flatten()
        .copied()
        .collect::<Vec<_>>();
    if supplied.is_empty()
        || supplied
            .iter()
            .any(|region| contract.permits_region(*region))
    {
        return None;
    }
    Some(
        type_error(
            function
                .return_type
                .as_ref()
                .map_or(function.span, |result| result.span),
            "returned reference does not outlive the callable's declared result lifetime",
        )
        .with_help(
            "return a parameter with the declared lifetime or add a valid longer-to-shorter outlives constraint",
        ),
    )
}

fn specialized_region_contract(
    source: &RegionContract,
    arguments: &[GeneratedArgument],
) -> RegionContract {
    RegionContract {
        param_regions: arguments
            .iter()
            .map(|argument| match argument {
                GeneratedArgument::Source(index) => {
                    source.param_regions.get(*index).copied().flatten()
                }
                GeneratedArgument::Capture { .. } => None,
            })
            .collect(),
        result_region: source.result_region,
        result_variance: source.result_variance,
        universal_facts: source.universal_facts.clone(),
    }
}

#[derive(Clone)]
struct EffectOperationInfo {
    protocol: u32,
    operation: u32,
    params: Vec<TypeId>,
    result: TypeId,
    terminal: bool,
    resumption_lower: u32,
    resumption_upper: Option<u32>,
    static_label_params: Vec<usize>,
    static_label_payloads: BTreeMap<usize, TypeId>,
    span: Span,
}

type EffectOperationMap = BTreeMap<(String, String), EffectOperationInfo>;

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct EffectInstanceKey {
    declaration: String,
    /// Runtime-erased arguments which still participate in protocol identity.
    static_arguments: Vec<EffectStaticArgument>,
    arguments: Vec<TypeId>,
}

struct EffectTypeResolution<'a> {
    ids: &'a BTreeMap<&'a str, TypeId>,
    aliases: &'a BTreeMap<String, ResolvedType>,
    array_name: Option<&'a str>,
    reference_types: &'a ReferenceTypes,
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
enum EffectStaticArgument {
    ConstU32(u32),
    ConstQuantity(u32, Option<u32>),
    Brand(String),
    LabelBrand(usize, typeck::ProvisionalType),
}

fn effect_protocol_display_name(key: &EffectInstanceKey) -> String {
    if key.static_arguments.is_empty() {
        return key.declaration.clone();
    }
    let arguments = key
        .static_arguments
        .iter()
        .map(|argument| match argument {
            EffectStaticArgument::ConstU32(value) => format!("const-u32:{value}"),
            EffectStaticArgument::ConstQuantity(lower, upper) => format!(
                "const-quantity:{lower}:{}",
                upper.map_or_else(|| "infinity".to_owned(), |upper| upper.to_string())
            ),
            EffectStaticArgument::Brand(brand) => format!("brand:{brand}"),
            EffectStaticArgument::LabelBrand(position, brand) => {
                let identity = match brand {
                    typeck::ProvisionalType::Nominal(instance) => &instance.declaration.0,
                    _ => "<invalid-label-brand>",
                };
                format!("label:{position}:{identity}")
            }
        })
        .collect::<Vec<_>>()
        .join(",");
    format!("{}<{arguments}>", key.declaration)
}
