                    let span = argument.span;
                    let MirFlow::Value(value) = self.expression(argument) else {
                        return MirFlow::Diverged;
                    };
                    lowered_args.push(Self::operand(
                        self.materialize(value, span),
                        mir::UseMode::Move,
                    ));
