    #[test]
    fn switch_edges_use_deterministic_synthetic_transfer_blocks() {
        let switched = function(
            0,
            "switch",
            I64,
            vec![UNIT, U32, I64, I64, I64, I64],
            vec![
                block(
                    0,
                    vec![],
                    vec![
                        statement(mir::InstructionKind::Const {
                            dst: 1,
                            value: Constant::U32(1),
                        }),
                        statement(mir::InstructionKind::Const {
                            dst: 2,
                            value: Constant::I64(10),
                        }),
                        statement(mir::InstructionKind::Const {
                            dst: 3,
                            value: Constant::I64(20),
                        }),
                    ],
                    mir::Terminator::Switch {
                        discr: operand(1, mir::UseMode::Copy),
                        cases: vec![(
                            Constant::U32(1),
                            mir::Edge {
                                target: 1,
                                args: vec![operand(2, mir::UseMode::Move)],
                            },
                        )],
                        otherwise: mir::Edge {
                            target: 2,
                            args: vec![operand(3, mir::UseMode::Move)],
                        },
                    },
                ),
                block(
                    1,
                    vec![parameter(4, I64, mir::BlockParamRole::Ordinary)],
                    vec![],
                    mir::Terminator::Return {
                        value: Some(operand(4, mir::UseMode::Move)),
                    },
                ),
                block(
                    2,
                    vec![parameter(5, I64, mir::BlockParamRole::Ordinary)],
                    vec![],
                    mir::Terminator::Return {
                        value: Some(operand(5, mir::UseMode::Move)),
                    },
                ),
            ],
        );
        let emitted = artifact(std::slice::from_ref(&switched));
        let Instruction::Switch {
            cases, otherwise, ..
        } = &emitted.code[3]
        else {
            panic!("switch remains the fourth instruction")
        };
        assert_eq!(cases[0].1, 6);
        assert_eq!(*otherwise, 9);
        assert_eq!(
            Vm::new(verify(emitted).unwrap()).run(0, vec![]).unwrap(),
            Value::I64(10)
        );
    }

